namespace LifeVerse.Api.Modules.Platform;

/// <summary>
/// The page of the administration panel (/admin). It holds no secret: the administrator types the access token and the MFA token, which stay in the memory of the page and go in the headers of each call to the
/// admin API (which checks them again). Everything that comes from the server is put in the page as text (never as HTML); every change asks for a reason and for confirmation.
/// </summary>
public static class AdminPanelPage
{
    public static string Html => Page;

    private const string Page = """
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LifeVerse · Administração</title>
<style>
