button{cursor:pointer;background:#252d33}button:hover{border-color:var(--accent)}button.primary{background:#0a3a3c;border-color:var(--accent)}button.warn{border-color:var(--orange)}button.bad{border-color:var(--danger);color:var(--danger)}button:disabled{opacity:.5;cursor:default}
